using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. Sarah Chen",
            InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy."
        },
        new()
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. James Rodriguez",
            InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and computational complexity. He previously worked at Google Research before joining the faculty."
        },
        new()
        {
            Id = 3, CourseCode = "CS 350", Title = "Database Systems",
            Description = "Design and implementation of database systems. Covers relational model, SQL, normalization, transaction processing, and introduction to NoSQL databases.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, IsFeatured = false,
            InstructorName = "Prof. Maria Gonzalez",
            InstructorBio = "Prof. Gonzalez brings industry experience from her decade at Oracle. Her research focuses on distributed database systems and query optimization."
        },
        new()
        {
            Id = 4, CourseCode = "MATH 101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, IsFeatured = true,
            InstructorName = "Dr. Robert Kim",
            InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible. He has authored two popular textbooks on introductory mathematics."
        },
        new()
        {
            Id = 5, CourseCode = "MATH 220", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Applications to computer graphics and data science.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, IsFeatured = false,
            InstructorName = "Dr. Amara Okafor",
            InstructorBio = "Dr. Okafor's research bridges pure mathematics and machine learning applications. She holds joint appointments in Mathematics and Data Science."
        },
        new()
        {
            Id = 6, CourseCode = "ENG 110", Title = "Academic Writing",
            Description = "Development of critical reading and writing skills for academic contexts. Emphasis on argumentation, research methods, and clear prose.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Prof. David Thompson",
            InstructorBio = "Prof. Thompson is a published author and rhetoric scholar. He has helped thousands of students develop strong writing foundations over his 20-year career."
        },
        new()
        {
            Id = 7, CourseCode = "ENG 250", Title = "American Literature",
            Description = "Survey of major American literary works from the colonial period to the present. Analysis of themes, styles, and cultural contexts.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Dr. Lisa Park",
            InstructorBio = "Dr. Park specializes in 20th-century American fiction and has published critical essays on Faulkner, Morrison, and Pynchon."
        },
        new()
        {
            Id = 8, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Calculus-based approach to Newtonian mechanics, energy, momentum, and oscillations.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentId = 4, IsFeatured = true,
            InstructorName = "Dr. Elena Volkov",
            InstructorBio = "Dr. Volkov is a former CERN researcher who brings cutting-edge physics insights to undergraduate education. She is known for her engaging demonstrations."
        },
        new()
        {
            Id = 9, CourseCode = "PHYS 220", Title = "Electromagnetism",
            Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics. Prerequisite: PHYS 101 and MATH 101.",
            Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Lab Fri 2:00–4:00 PM", DepartmentId = 4, IsFeatured = false,
            InstructorName = "Dr. Marcus Williams",
            InstructorBio = "Dr. Williams conducts research in photonics and optical communications. He has been recognized with multiple teaching excellence awards."
        },
        new()
        {
            Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from antiquity through the medieval period. Examines political, social, economic, and cultural developments across regions.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Dr. Catherine Miller",
            InstructorBio = "Dr. Miller is a medievalist whose research focuses on cross-cultural exchange along ancient trade routes. She has conducted fieldwork across three continents."
        },
        new()
        {
            Id = 11, CourseCode = "HIST 315", Title = "The Modern Middle East",
            Description = "Political and social history of the Middle East from the Ottoman Empire to the present. Explores colonialism, nationalism, and contemporary conflicts.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Dr. Ahmed Hassan",
            InstructorBio = "Dr. Hassan is an expert in modern Middle Eastern politics and has served as a consultant for international policy organizations."
        },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

